import numpy as np
from scipy.optimize import least_squares
S=df.S.values; I=df.I.values; v=df.v.values
def mk(kind):
    def f(p,S,I):
        Vm=p[0]; Km=p[1]; Ki=p[2]
        if kind=='comp': return Vm*S/(Km*(1+I/Ki)+S)
        if kind=='uncomp': return Vm*S/(Km+S*(1+I/Ki))
        if kind=='noncomp': return Vm*S/((Km+S)*(1+I/Ki))
        if kind=='mixed':
            Ki2=p[3]; return Vm*S/(Km*(1+I/Ki)+S*(1+I/Ki2))
        if kind=='none': return Vm*S/(Km+S)
    return f
res={}
for kind,n in [('none',2),('comp',3),('uncomp',3),('noncomp',3),('mixed',4)]:
    f=mk(kind); best=None
    for Ki0 in [0.1,0.5,1,3,10]:
        for Km0 in [0.5,2,8]:
            p0=[10,Km0,Ki0,Ki0][:n]
            try:
                r=least_squares(lambda p: f(p,S,I)-v, p0, bounds=(1e-6,1e4))
                if best is None or r.cost<best.cost: best=r
            except Exception as e: pass
    rss=2*best.cost; N=len(v); k=n+1
    bic=N*np.log(rss/N)+k*np.log(N)
    res[kind]=best
    print(kind, np.round(best.x,4), 'RSS',round(rss,4),'BIC',round(bic,2))
    if kind in('comp','uncomp','noncomp'):
        J=best.jac; s2=rss/(N-n); cov=np.linalg.inv(J.T@J)*s2
        print('  relSE',np.round(np.sqrt(np.diag(cov))/best.x,3))
for kind in ['comp','noncomp','uncomp']:
    r=res[kind].fun
    print(kind,'resid by I:',[round(float(np.mean(r[I==i])),3) for i in [0,0.5,1,2]])

