import numpy as np
from scipy.optimize import least_squares
S=df.S.values.astype(float); I=df.I.values.astype(float); v=df.v.values.astype(float)
def f(p,kind):
    Vm,Km,Ki=p[0],p[1],p[2]
    if kind=='comp': return Vm*S/(Km*(1+I/Ki)+S)
    if kind=='uncomp': return Vm*S/(Km+S*(1+I/Ki))
    if kind=='noncomp': return Vm*S/((Km+S)*(1+I/Ki))
    if kind=='mixed': return Vm*S/(Km*(1+I/Ki)+S*(1+I/p[3]))
    if kind=='none': return Vm*S/(Km+S)
res={}
for kind,n in [('none',2),('comp',3),('uncomp',3),('noncomp',3),('mixed',4)]:
    best=None
    for Ki0 in [0.1,0.5,1,3,10]:
        for Km0 in [0.5,2,8]:
            p0=np.array([10,Km0,Ki0,Ki0])[:n] if kind!='none' else np.array([10,Km0])
            try:
                r=least_squares(lambda p: f(p,kind)-v, p0, bounds=(1e-6,1e4))
                if best is None or r.cost<best.cost: best=r
            except Exception as e: err=e
    if best is None: print(kind,'fail',err); continue
    rss=2*best.cost; N=len(v); k=n+1
    bic=N*np.log(rss/N)+k*np.log(N)
    res[kind]=best
    print(kind, np.round(best.x,4), 'RSS',round(rss,4),'BIC',round(bic,2))
    if kind in('comp','uncomp','noncomp','mixed'):
        J=best.jac; s2=rss/(N-n); cov=np.linalg.pinv(J.T@J)*s2
        print('  relSE',np.round(np.sqrt(np.abs(np.diag(cov)))/np.abs(best.x),3))
    r=best.fun
    print('  resid mean by I:',[round(float(np.mean(r[I==i])),3) for i in [0,0.5,1,2]])

